-- =============================================
-- Create push_subscription
--
-- One row per browser push endpoint. Deliberately **account-scoped**:
-- `user_id` is the login account, not any product's business entity — a device
-- is a property of the signed-in account, not of one business domain.
--
-- `endpoint` is a capability URL generated by the push service. It is unique:
-- when the same browser signs in with another account, the upsert rebinds the
-- row instead of leaving two owners for one device.
-- =============================================

CREATE TABLE push_subscription (
    id         VARCHAR(64)   PRIMARY KEY,
    user_id    VARCHAR(64)   NOT NULL,
    endpoint   VARCHAR(2048) NOT NULL,
    p256dh     VARCHAR(255)  NOT NULL,
    auth       VARCHAR(255)  NOT NULL,
    user_agent VARCHAR(500),
    created_at BIGINT        NOT NULL,
    updated_at BIGINT        NOT NULL
);

CREATE UNIQUE INDEX uk_push_subscription_endpoint ON push_subscription (endpoint);
CREATE INDEX idx_push_subscription_user ON push_subscription (user_id, updated_at DESC);
